from __future__ import absolute_import
from hran_radio.radio_connection.rmod_51_connection import AddKeyToKnownHost
from hran_radio.exceptions import KeyVerificationError
from taf.transport.ssh import CommandOutputTimeoutError
from hran_radio.exceptions import ConnectionError
from .base_connection import BaseConnection
from .base_connection import ConnectionSSH
import re
import six


def check_output(output):
    output = six.ensure_str(output, encoding="latin")
    if re.search(
            r"Host key verification failed", output
    ) or re.search(
        r"can\'t be established", output
    ):
        raise KeyVerificationError()


class FrmonConnection(BaseConnection):
    def __init__(self, radio_ip, sm_ip, msm_ip):
        super(FrmonConnection, self).__init__(radio_ip, sm_ip, msm_ip)
        self.frmon_ip = None
        self.execute_command_on_msm = False
        self.ommit_frmon = False

    def set_frmon_ip(self, ip):
        """
        Set frmon ip

        :param ip: ip address str()
        :return: None
        """
        self.frmon_ip = ip

    def execute_commands(self, cmd, rel):
        """
        Execute command

        :param cmd: command str
        :param rel: FSMF or ASIA str
        :return: Command output str
        """
        if rel == "FSMF":
            stdout = self.run_command_from_rel3(cmd)
        else:
            stdout = self.run_command_from_rel4(cmd)
        return stdout

    def wrap_command_for_rel3(self, cmd):
        """
        Return full command prepare to execute from smod rel3 on rmod 5.1

        :param cmd: command str
        :return: full command
        :rtype: str
        """
        if self.execute_command_on_msm:
            return ('''{cmd}'''.format(
                cmd=cmd)
            )
        if self.ommit_frmon:
            return (
                "ssh root@{rmod_ip} '{cmd}'".format(cmd=cmd, rmod_ip=self._radio_ip)
            )
        return (
            "echo $'{cmd}' > command_set_hran_radio; ssh root@{rmod_ip} 'frmonShellClient {frmon_ip} 2000' < command_set_hran_radio;"
            "rm command_set_hran_radio;".format(
                cmd=cmd, rmod_ip=self._radio_ip, frmon_ip=self.frmon_ip
            )
        )

    def wrap_command_for_rel4(self, cmd, num):
        """
        Return full command prepare to execute from smod rel4 on rmod 5.1

        :param cmd: command str
        :param num: 1 or 2 as a str. (Left, right side smod)
        :return: full command
        :rtype: str
        """
        if self.execute_command_on_msm:
            return ('''lxc-attach -n 0x{num}018 {cmd}'''.format(
                cmd=cmd, num=num)
            )
        if self.ommit_frmon:
            return ('''lxc-attach -n 0x{num}018 ssh root@{rmod_ip} "{cmd}"'''.format(
                cmd=cmd, num=num, rmod_ip=self._radio_ip)
            )
        return (
            "echo $'{}' > command_set_hran_radio; lxc-attach -n 0x{}018 ssh root@{} 'frmonShellClient {} 2000' < command_set_hran_radio;"
            "rm command_set_hran_radio;".format(cmd, num, self._radio_ip, self.frmon_ip)
        )

    def run_command_from_rel3(self, command):
        """
        Execute command on smod release3

        :param command: command str
        :return: command output
        :rtype: str
        """
        output = self._execute_command_rel3(command)
        if self.key_error.search(six.ensure_str(output.stdout)):
            self._add_key()
            output = self._execute_command_rel3(command)
            check_output(output.stdout)
        if output.return_code != 0:
            raise ConnectionError
        return six.ensure_str(output.stdout)

    def run_command_from_rel4(self, command):
        """
        Execute command on smod release4

        :param command: command str
        :return: command output
        :rtype: str
        """
        try:
            output, num = self._try_on_both_side(command)
            check_output(output.stdout)
        except (KeyVerificationError, CommandOutputTimeoutError):
            self._add_key(num="1")
            self._add_key(num="2")
            output, num = self._try_on_both_side(command)
            check_output(output.stdout)
        if output.return_code != 0:
            raise ConnectionError
        return six.ensure_str(output.stdout)

    def _add_key(self, num=None):
        key = AddKeyToKnownHost()
        key.login_to_msm()
        if not self._sm_ip == key.msm_ip and not self._sm_ip == "192.168.255.1":
            key.login_to_esm()
        key.add_key(radio_ip=self._radio_ip, num=num)
        key.close_connection()

    def send_file_to_msm(self, filename, target_directory):
        ssh = ConnectionSSH(self._sm_ip)
        ssh.connect()
        ssh.upload_file(filename, target_directory)
        ssh.disconnect()

    def remove_file_from_msm(self, filename):
        ssh = ConnectionSSH(self._sm_ip)
        ssh.connect()
        ssh.remove_file(filename)
        ssh.disconnect()

    def send_file_to_esm(self, filename, destination):
        connection = ConnectionSSH(self._sm_ip, self._msm_ip)
        response = connection.put_file_on_remote(filename, destination)
        return response

    def run_command_on_esm(self, cmd):
        connection = ConnectionSSH(self._sm_ip, self._msm_ip)
        connection.connect_to_via_proxy()
        response = connection.run_command(cmd)
        return response
